def gate(req):
    if superseded_by_higher_seq(req):      # moved above the DENY clauses
        return SUPERSEDED
    if "block" in req.policy:
        return DENY
    if req.evidence is None:
        return NEEDS_INPUT
    if req.evidence == []:
        return DENY
    return APPROVE

